・一式工事とは、総合的な企画・指導・調整のもとに土木工作物や建築物を建設する工事で、元請の立場を想定した業種。一式工事の許可があっても、専門工事を単独で請け負うには当該専門工事の許可が別に必要★。
・電気通信工事→有線電気通信設備、無線電気通信設備、ネットワーク設備、情報設備、放送機械設備等の電気通信設備を設置する工事。例：携帯基地局設置、構内LAN、CATV、監視カメラ、防災行政無線。
