・主たる工事に附帯する他業種の工事（附帯工事）は、その業種の許可がなくても一体として請け負える。ただし附帯工事の額が500万円以上なら、その業種の主任技術者となれる資格者を置いて自ら施工するか、許可業者に下請させる必要がある。

