━━━━━━━━━━━━━━━━━━━━━━
・建設業者は、請負契約を締結するに際して、工事内容に応じ、工事の種別ごとの材料費・労務費その他の経費の内訳、工事の工程ごとの作業とその準備に必要な日数を明らかにして、見積りを行うよう努めなければならない。
