○現場代理人との兼務：同一現場であれば主任技術者・監理技術者が現場代理人を兼ねることは可○。
○営業所技術者は、当該営業所で契約した近接現場で職務を兼ねられる特例あり。
×専任現場の技術者が他社の技術者を兼ねることは一切不可。技術者は所属建設業者と直接的かつ恒常的な雇用関係にある者でなければならない★（在籍出向者や派遣労働者は不可）。

