        body: `▼ゼロから：現場に置いた技術者は何をする人なのか。そして重層下請の現場で「どの会社が何を施工しているか」を見える化する仕組みが施工体制台帳と施工体系図です。丸投げや無資格施工を防ぐための台帳であり、作成義務者・作成条件・保存や掲示の方法が細かく問われます。最後に、建設業法に違反したときの罰則の重さの序列も押さえます。「どの違反が一番重いか」という形の出題があるため、代表的な罰則を3段階で整理しておきましょう。

━━━━━━━━━━━━━━━━━━━━━━
🔑 主任技術者・監理技術者の職務（第26条の4）
━━━━━━━━━━━━━━━━━━━━━━
・主任技術者および監理技術者は、工事現場における建設工事を適正に実施するため、当該建設工事の施工計画の作成、工程管理、品質管理その他の技術上の管理および当該建設工事の施工に従事する者の技術上の指導監督の職務を誠実に行わなければならない★。
・監理技術者は、これに加えて下請負人を適切に指導監督するという総合的な役割を担う。
・工事の施工に従事する者は、主任技術者・監理技術者がその職務として行う指導に従わなければならない★。
・×「請負代金の管理」「下請契約の締結」「資金計画」は技術者の職務ではない（現場代理人や経営側の仕事）。職務として挙げる選択肢の中に契約事務を混ぜるひっかけが定番。

━━━━━━━━━━━━━━━━━━━━━━
🔑 施工体制台帳と施工体系図（第24条の8）
━━━━━━━━━━━━━━━━━━━━━━
・作成義務者：発注者から直接建設工事を請け負った特定建設業者で、下請契約の総額が4,500万円以上（建築一式7,000万円以上）となるもの★。
・記載事項：下請負人の商号・名称、下請工事の内容と工期、下請負人の許可番号、主任技術者の氏名など。二次下請以下を含むすべての下請負人を記載する。
・下請負人は、その請け負った工事を再下請に出したときは、再下請負通知書を元請に提出する★。
・台帳は工事現場ごとに備え置き、発注者から請求があったときは閲覧に供する★。
・施工体系図：各下請負人の施工分担関係を表示した図を作成し、工事現場の見やすい場所に掲げる★。
・公共工事の特例（入契法）：公共工事では下請金額にかかわらず施工体制台帳を作成し、その写しを発注者に提出しなければならない★。施工体系図は工事関係者が見やすい場所および公衆が見やすい場所に掲げる。
・帳簿：建設業者は営業所ごとに帳簿を備え、5年間（住宅新築工事の場合10年間）保存する。

【図解】施工体制台帳のポイント
　項目｜民間工事｜公共工事
　作成条件｜下請総額4,500万円以上★｜金額を問わず作成★
　発注者への対応｜請求があれば閲覧｜写しを提出★
　施工体系図｜現場の見やすい場所に掲示｜公衆も見やすい場所に掲示
　⚠作成義務者はいずれも発注者から直接請け負った特定建設業者（公共は元請全般）

━━━━━━━━━━━━━━━━━━━━━━
🔑 建設業法の罰則の序列
━━━━━━━━━━━━━━━━━━━━━━
・最も重い（3年以下の拘禁刑または300万円以下の罰金）★：
　○許可を受けないで建設業を営んだ者（無許可営業）
　○特定建設業の許可を受けずに4,500万円以上の下請契約を締結した者
　○営業停止処分・営業禁止処分に違反して営業した者
・6月以下の拘禁刑または100万円以下の罰金：虚偽・不正の事実に基づいて許可を受けた者。
・100万円以下の罰金：主任技術者・監理技術者を置かなかった者★、許可行政庁の報告徴収・検査を拒んだ者。
・50万円以下の罰金：変更届出を怠った者・虚偽届出、施工体制台帳関係の違反等。
・10万円以下の過料：廃業等の届出を怠った者、帳簿の備付け違反等。
・法人重科：無許可営業等の重い違反は、法人に対して1億円以下の罰金★。
・刑罰とは別に、監督処分（指示→営業停止→許可取消し）がある。一括下請負違反は営業停止以上の重い処分の対象。

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけと本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・×「施工体制台帳は一般建設業者も作成義務がある」→民間工事では元請特定建設業者のみ。
・×「台帳には一次下請のみ記載」→再下請以下すべて。
・×「民間工事でも台帳の写しを発注者に提出」→民間は請求があれば閲覧。提出は公共工事。
・×「施工体系図は営業所に備え置く」→現場に掲示。
・×「技術者不設置は3年以下の拘禁刑」→100万円以下の罰金。最重は無許可営業等。
・技術者の職務の列挙から「原価管理」「契約管理」を除かせる問題が近年頻出。

★ここだけ暗記
・技術者の職務＝施工計画作成・工程管理・品質管理・技術上の指導監督（契約事務は含まない）。
・施工体制台帳＝元請特定建設業者・下請総額4,500万円以上。公共工事は金額不問＋写し提出。
・罰則最重は無許可営業等（3年以下・法人1億円以下）、技術者不設置は100万円以下の罰金。`,
