・電気通信工事の現場では、建設業法上の主任技術者・監理技術者（施工管理全体の責任者）と、事業法上の工事担任者（端末設備等の接続工事の有資格者）は別の制度である★。施工管理技士の資格があっても、端末設備の接続工事を行うには工事担任者資格が別に必要。
