・電気通信事業者は、天災、事変その他の非常事態が発生し、または発生するおそれがあるときは、災害の予防もしくは救援、交通、通信もしくは電力の供給の確保または秩序の維持のために必要な事項を内容とする通信を優先的に取り扱わなければならない★。
