　→災害時に一般の通話を規制（発信規制）できる法的根拠。
・この場合、総務省令で定める基準に従って、電気通信業務の一部の停止または制限を行う。
・×「いかなる場合も通信を停止してはならない」→重要通信確保のためなら一部停止可。
・×「業務の停止にはあらかじめ総務大臣の許可が必要」→許可規定はない（省令の基準に従う）。

