　○空中線電力
	○運用許容時間
・語呂で「落成期限・型式周波数・識別信号・空中線電力・運用時間」とセット暗記。「無線設備の設置場所」「通信の相手方」は予備免許の指定事項ではない（申請書・免許状の記載事項との混同を誘う）★。
・予備免許中は、原則として電波を発射できない。試験電波の発射には所定の手続が必要。
