・予備免許を受けた者は、工事が落成したときは、その旨を総務大臣に届け出て、その無線設備、無線従事者の資格・員数、時計・書類について検査を受けなければならない★（落成後の検査＝落成検査）。
　→検査対象は「設備・人・時計・書類」の4点セット★。
・登録検査等事業者等による点検の結果を活用することで、検査の一部を省略できる制度がある。
・総務大臣は、落成検査の結果が規定に適合していると認めるときは、遅滞なく申請者に免許を与える。免許を与えたときは免許状を交付する★。
・簡易な免許手続：適合表示無線設備のみを使用する特定無線局（携帯電話端末など多数開設されるもの）や一定の局には、予備免許・落成検査を経ない包括免許・簡易手続の制度がある。

【図解】免許取得の流れ
　段階｜内容
　申請→審査｜技術基準適合・周波数割当て可能性等★
　予備免許｜5事項の指定（落成期限・型式周波数・識別信号・空中線電力・運用許容時間）★
	落成届→落成検査｜設備・従事者・時計・書類を検査★
　免許・免許状交付｜検査適合なら遅滞なく免許
　⚠免許を受けるまで電波は出せない。工事完了＝運用開始ではない

━━━━━━━━━━━━━━━━━━━━━━
