　→アンテナの雷対策。周波数の高い小型空中線には例外がある。
・工事実務では、鉄塔上のアンテナ・同軸ケーブルの接地、避雷器（アレスタ）の設置がこの規定の具体化。

【図解】無線設備の基準
　規定｜要点
　電波の質｜周波数の偏差・幅、高調波の強度等★
　受信設備｜副次的に発する電波が限度以下★
　高圧電気｜容易に触れられない構造・しゃへい
　空中線系｜避雷器または接地装置★
　⚠空中線電力は「電波の質」の要素ではない

