・対象は「特定の相手方に対して行われる無線通信」。不特定向けの放送は対象外。
・罰則：秘密を漏らし窃用した者は1年以下の拘禁刑または50万円以下の罰金、無線通信の業務に従事する者は2年以下の拘禁刑または100万円以下の罰金に加重。
・このほか運用面の義務として、無線通信は正確に行い、通信上の誤りを知ったときは直ちに訂正する、無線業務日誌の記載などがある。

