・×「電子レンジの設置には常に個別の許可が必要」→型式確認等を受けた設備は不要。
・×「高周波利用設備は電波法の適用を受けない」→電波法第100条の適用を受ける。
・×「障害を与えた場合でも措置命令の規定はない」→必要な措置を命ずることができる。
