★ここだけ暗記
・目的＝危害防止基準の確立・責任体制の明確化・自主的活動の促進→安全と健康の確保＋快適な職場環境の形成。
・労働災害＝業務起因の負傷・疾病・死亡。事業者＝労働者を使用する事業経営主体。
