・地山の掘削作業主任者：掘削面の高さが2メートル以上となる地山の掘削の作業★（技能講習）。管路埋設のための開削工事で該当。
・土止め支保工作業主任者：土止め支保工の切りばりまたは腹おこしの取付けまたは取外しの作業★（技能講習）。
・足場の組立て等作業主任者：つり足場、張出し足場または高さが5メートル以上の構造の足場の組立て、解体または変更の作業★（技能講習）。
・型枠支保工の組立て等作業主任者：型枠支保工の組立てまたは解体の作業（技能講習）。
・酸素欠乏危険作業主任者：酸素欠乏危険場所における作業★。マンホール・暗きょ・ピット内の通信ケーブル工事は硫化水素中毒の危険も想定される第二種酸素欠乏危険作業に該当することが多く、第二種の技能講習修了者が必要★。
・石綿作業主任者：石綿等を取り扱う作業（既設建物の改修で石綿含有建材に触れる場合）。
