━━━━━━━━━━━━━━━━━━━━━━
・事業者は、労働者に対し、医師、保健師その他の省令で定める者による心理的な負担の程度を把握するための検査（ストレスチェック）を、1年以内ごとに1回、定期に行わなければならない★。
