━━━━━━━━━━━━━━━━━━━━━━
・この法律で定める基準に達しない労働条件を定める労働契約は、その部分については無効とする。この場合において、無効となった部分は、この法律で定める基準による★。
　→契約全体が無効になるのではなく、達しない部分だけが無効となり、法定基準に自動的に置き換わる★（最頻出）。
