━━━━━━━━━━━━━━━━━━━━━━
・×「1年継続勤務で10日付与」→6箇月継続勤務。
・×「上限は6年6箇月で25日」→20日。
・×「使用者は業務多忙なら年休の請求を拒否できる」→時季の変更ができるだけで拒否は不可。
・×「利用目的が相当でない場合は不許可にできる」→利用目的は自由。
・×「年5日の取得は労働者の努力義務」→使用者の時季指定義務（罰則付き）。
・×「業務上のけがで休業した期間は欠勤扱い」→出勤とみなす。
・×「年休の時効は1年」→2年（繰越可）。
・計画的付与で「全日数を計画的に割り振れる」とする誤り→5日は残す。

【学習メモ】基準日を統一して付与する斉一的取扱いなど、実務の付与方式も出題されることがある。半日単位の年休は労使協定がなくても運用できるとされる点は、時間単位年休（労使協定が必須・年5日以内）との対比で覚えておこう。

★ここだけ暗記
・6箇月＋8割出勤で10日、6年6箇月以上で20日。時効2年。
・使用者にあるのは時季変更権のみ。目的自由・不利益取扱い禁止。
