━━━━━━━━━━━━━━━━━━━━━━
・常時10人以上の労働者を使用する使用者は、就業規則を作成し、行政官庁（労働基準監督署長）に届け出なければならない★。変更した場合も同様。
・作成・変更について、過半数組合（ないときは過半数代表者）の意見を聴かなければならない★。
　→「意見を聴く」であって「同意を得る」「協議して決定する」ではない★（最頻出）。反対意見でも、意見書を添付して届け出れば手続上は有効。
・絶対的必要記載事項★：
