・労災保険法に基づいて災害補償に相当する給付が行われるべき場合は、使用者は補償の責を免れる★（実務では労災保険が一次的役割）。
・重大な過失の特例：労働者が重大な過失によって業務上負傷し、その過失について署長の認定を受けた場合は、休業補償・障害補償を行わなくてよい。

