        body: `▼ゼロから：電柱を道路に建てる、通信ケーブルを道路の上空に渡す、管路を道路の下に埋める。これらはすべて道路という公共物を「継続して」使う行為であり、道路管理者の占用許可が必要です。電気通信工事は道路との関わりが深く、この占用許可は試験でも実務でも避けて通れません。押さえるのは、許可権者（道路管理者）、申請書の記載事項、警察の道路使用許可との関係（相互経由申請）の3点です。「継続使用＝占用（道路管理者）」「一時使用＝使用（警察署長）」の対比を軸にしましょう。

━━━━━━━━━━━━━━━━━━━━━━
🔑 道路の占用許可（第32条）★
━━━━━━━━━━━━━━━━━━━━━━
・道路に次の工作物・物件・施設を設け、継続して道路を使用しようとする場合は、道路管理者の許可を受けなければならない★。
	○電柱、電線、変圧塔、郵便差出箱、公衆電話所、広告塔その他これらに類する工作物★
	○水管、下水道管、ガス管その他これらに類する物件（通信用の管路・とう道もこの類型）★
	○鉄道、軌道、自動運行補助施設
	○歩廊、雪よけその他これらに類する施設
	○地下街、地下室、通路、浄化槽その他これらに類する施設
	○露店、商品置場その他これらに類する施設
　○前各号のほか政令で定める工作物・物件・施設
・「継続して」使用することがポイント★。電柱・電線・地下管路は典型的な占用物件。
・占用の期間・場所・構造等を変更しようとするときも、あらかじめ道路管理者の許可が必要★。
・占用者は占用料を徴収されることがある。無許可占用には監督処分・罰則がある。

━━━━━━━━━━━━━━━━━━━━━━
🔑 申請書の記載事項★
━━━━━━━━━━━━━━━━━━━━━━
・占用許可申請書に記載する事項：
	○道路の占用の目的
	○道路の占用の期間
	○道路の占用の場所
	○工作物、物件または施設の構造
	○工事実施の方法
	○工事の時期
	○道路の復旧方法★
・この7項目の列挙から抜き差しする問題が定番。「工事費の額」「施工業者名」は記載事項ではない★。
・道路管理者は、国道（指定区間）は国土交通大臣、都道府県道は都道府県、市町村道は市町村★。どの道路かで申請先が変わる。
・電線・水道管・ガス管・鉄道など公益性の高い物件は、道路の敷地外に余地がなくやむを得ず、政令の基準に適合する場合には、道路管理者は許可を与えなければならない（義務占用）とされる★。

【図解】占用と使用の対比
　項目｜道路占用｜道路使用
	根拠法｜道路法第32条★｜道路交通法第77条
	許可権者｜道路管理者★｜所轄警察署長★
　対象｜電柱・管路等の継続使用｜工事・作業等の一時使用
　典型例｜通信ケーブルの添架・埋設｜ケーブル敷設工事の作業帯
	⚠1つの工事で両方の許可が必要になることが多い

━━━━━━━━━━━━━━━━━━━━━━
🔑 道路使用許可との相互経由申請★
━━━━━━━━━━━━━━━━━━━━━━
・道路の占用が道路交通法の道路使用許可も必要な行為である場合、占用許可の申請書は所轄警察署長を経由して道路管理者に提出することができ、道路使用許可の申請書は道路管理者を経由して警察署長に提出することができる★（相互に経由申請が可能）。
　→申請者の利便のための制度。「両方の窓口に別々に出さなければならない」とする肢は誤り（別々でも出せるが、経由もできる）。
・道路管理者と警察署長は相互に協議・意見聴取する仕組みがある。
・工事実施段階では、道路を掘削する場合の埋戻し・舗装復旧の方法、保安施設の設置など、許可条件として付されるのが通例。占用工事の施工不良による陥没事故は施工管理上の重大リスク。

━━━━━━━━━━━━━━━━━━━━━━
🔑 頻出ひっかけと本試験での問われ方
━━━━━━━━━━━━━━━━━━━━━━
・×「電柱を道路に設置するには警察署長の占用許可が必要」→占用許可は道路管理者★。
・×「占用許可を受ければ道路使用許可は不要」→工事・作業には別途使用許可が必要な場合が多い。
・×「占用期間の変更は事後届出でよい」→あらかじめ許可。
・×「申請書には道路の復旧方法は記載不要」→記載事項★。
・×「電線類の占用はいかなる場合も拒否できる」→義務占用の要件を満たせば許可しなければならない。
・「継続して使用」の文言を「一時的に使用」と替えて占用と使用を入れ替えるのが王道のひっかけ。

【学習メモ】占用許可（道路管理者の財産・構造管理）と使用許可（警察の交通管理）という視点の違いで整理すると忘れない。地下埋設物の占用位置（歩道下・車道下の別）や土かぶり（埋設深さ）は、政令の基準と道路管理者の定めにより細かく決められている。

★ここだけ暗記
・継続使用＝占用＝道路管理者の許可。電柱・電線・管路が典型。
・申請書＝目的・期間・場所・構造・工事実施方法・工事時期・復旧方法。
・警察の使用許可とは別制度。申請書は相互経由提出が可能。`,
