━━━━━━━━━━━━━━━━━━━━━━
・目的：河川について、洪水、津波、高潮等による災害の発生が防止され、河川が適正に利用され、流水の正常な機能が維持され、および河川環境の整備と保全がされるように総合的に管理することにより、国土の保全と開発に寄与し、公共の安全を保持し、公共の福祉を増進する。
