	○点検の内容：機器点検（6月ごと）・総合点検（1年ごと）。
	○報告の頻度：特定防火対象物は1年に1回★、その他（非特定）は3年に1回★。
・一定規模以上の防火対象物では、消防設備士または消防設備点検資格者に点検させなければならない。
・×「点検結果は保存すれば報告不要」→消防長・消防署長への報告義務がある。
