	○災害対策分野：被災者生活再建支援金の支給等
・事業者の実務では、従業員・報酬支払先のマイナンバーを源泉徴収票や社会保険の届出書に記載するために取り扱う。
・目的外利用の禁止★：本人の同意があっても、法定された利用範囲を超えて利用してはならない★（個人情報保護法は同意があれば目的外利用可能である点と対比）。
	→社員番号やCADの管理番号としてマイナンバーを流用することは、本人が同意しても違法★。
・提供の制限：法定された場合を除き、特定個人情報の提供を求めること・提供すること・収集し保管することも禁止される★。

【図解】個人情報保護法との比較
　項目｜個人情報保護法｜マイナンバー法
	利用範囲｜利用目的の特定で足りる｜社会保障・税・災害対策に限定★
	本人同意による目的外利用｜可能｜同意があっても不可★
	提供｜同意等により可能｜法定の場合以外は不可★
	番号｜規定なし｜個人番号12桁・法人番号13桁
	⚠マイナンバー法は個人情報保護法の特別法として上乗せ規制

━━━━━━━━━━━━━━━━━━━━━━
