・安全管理措置：特定個人情報の漏えい・滅失・毀損の防止のため、組織的・人的・物理的・技術的安全管理措置を講ずる。事務取扱担当者の明確化、保管区域の管理、アクセス制御等。
・保管・廃棄：法定事務に必要がある間に限り保管でき、必要がなくなったら速やかに廃棄・削除する★。
