★ここだけ暗記
・定義＝電磁的方式の情報の漏えい・滅失・毀損の防止＋システムとネットワークの安全性・信頼性確保＋維持管理。
・重要社会基盤事業者（電気通信等）は自主的・積極的な確保と施策協力の努力義務。
