・会社は、毎事業年度の開始前に、事業計画を定め、総務大臣の認可を受けなければならない★（変更も同様）。
・取締役・監査役の選任等の決議、定款の変更、剰余金処分等の重要事項にも総務大臣の認可等の関与がある。外国人は持株会社・東西会社の取締役・監査役に原則就任できない。
・近年の法改正で、研究成果の開示義務の廃止など規制の一部見直しが行われているが、あまねく提供の責務・政府保有・外資規制という基本骨格は令和7年時点でも維持されている★。

━━━━━━━━━━━━━━━━━━━━━━
